# [HELPER] speech_client.py\n# Centralized configuration and helper utilities for IBM Watson Speech-to-Text\n# WebSocket integration.\n\nimport os\nfrom ibm_watson import SpeechToTextV1\nfrom ibm_watson.websocket import RecognizeCallback, AudioSource\n\n# ----------------------------------------------------------\n# Helper: create a ready-to-use SpeechToTextV1 client\n# ----------------------------------------------------------\ndef get_watson_client() -> SpeechToTextV1:\n    ""\"\n    Returns a configured SpeechToTextV1 instance using credentials\n    from environment variables.\n    Required env vars:\n      - IBM_STT_APIKEY\n      - IBM_STT_URL\n    """\n    apikey = os.getenv('IBM_STT_APIKEY')\n    url = os.getenv('IBM_STT_URL')\n    if not apikey or not url:\n        raise RuntimeError('Set IBM_STT_APIKEY and IBM_STT_URL environment variables')\n    return SpeechToTextV1(auth_type='iam', apikey=apikey, url=url)\n\n# ----------------------------------------------------------\n# Helper: create a RecognizeCallback with provider-specific flags\n# ----------------------------------------------------------\ndef create_recognize_callback(\n    on_connect: Callable[[], None],\n    on_data: Callable[[str], None],\n    on_error: Callable[[Exception], None],\n    on_close: Callable[[], None],\n    audio_format: str,\n    **kwargs,\n) -> RecognizeCallback:\n    \"\"\"\n    Builds a RecognizeCallback configured for live microphone streaming.\n    Additional keyword arguments are passed to the Watson constructor\n    (e.g., `punctuation`, `language_customization_id`).\n    """\n    return RecognizeCallback(\n        on_connect=on_connect,\n        on_data=on_data,\n        on_error=on_error,\n        on_close=on_close,\n        audio_format=audio_format,\n        **kwargs,\n    )\n\n# ----------------------------------------------------------\n# Helper: format Watson transcription JSON for downstream consumers\n# ----------------------------------------------------------\ndef format_transcription(payload: str) -> List[dict]:\n    \"\"\"\n    Parses a WebSocket JSON payload and returns a list of transcription\n    dictionaries compatible with the `PartialResultProcessor` in\n    partial_results.py.\n\n    Expected Watson payload example:\n    {\n        \"results\": [\n            {\n                \"alternatives\": [\n                    {\"transcript\": \"hello\", \"confidence\": 0.95},\n                ],\n                \"final\": true,\n            }\n        ]\n    }\n    \"\"\"\n    data = json.loads(payload)\n    return [\n        {\n            'transcript': alt['transcript'],\n            'final': result.get('final', False),\n        }\n        for result in data.get('results', [])\n        for alt in result.get('alternatives', [])\n    ]\n\n# ----------------------------------------------------------\n# Example usage (for testing)\n# ----------------------------------------------------------\nif __name__ == '__main__':\n    client = get_watson_client()  # simply verifies env vars\n    print('Watson client ready. Credentials loaded.')\n